<script setup lang="ts">
import { onMounted,ref,computed,watch } from 'vue'
import type { components } from '@adc/contracts'
import { createProtectedClient } from '../../api/protected'
import { ApiFailure,prepareCommand,UnknownOutcomeError,type PreparedCommand } from '../../api/http'
import { shiftDate } from '../schedules/week'
import {useAuthenticationStore} from '../../stores/authentication'
import {storeToRefs} from 'pinia'
import {useViewScope} from '../../stores/view-scope'
import {useUnsaved} from '../../composables/useUnsaved'
import type {AppointmentSummary} from '../../api/workspace-types'
import WorkspacePanel from '../../components/WorkspacePanel.vue'
import AppointmentActions from '../../components/AppointmentActions.vue'
type Catalog=components['schemas']['CatalogItem'];type Candidate=components['schemas']['Candidate'];type Patient=components['schemas']['PatientView'];type Appointment=AppointmentSummary
const auth=useAuthenticationStore(),api=createProtectedClient(),clinics=ref<Catalog[]>([]),treatments=ref<Catalog[]>([]),selectedTreatments=ref<string[]>([]),slots=ref<Candidate[]>([]),slot=ref<Candidate|null>(null),appointments=ref<Appointment[]>([]),patient=ref<Patient|null>(null),records=ref<components['schemas']['AllergyView'][]>([]),verification=ref(''),number=ref(''),birth=ref(''),basis=ref(''),person=ref(false),confirmed=ref(false),error=ref(''),notice=ref(''),busy=ref(false),unknown=ref(false),candidateNext=ref<string|null>(null),appointmentNext=ref<string|null>(null)
const can=(capability:string)=>auth.canAccess('RECEPTION',capability)
const scope=useViewScope(),{clinic,date}=storeToRefs(scope),drawer=ref(false),step=ref(1),status=ref(''),doctor=ref(''),doctors=ref<Catalog[]>([]),view=ref('list'),treatmentSearch=ref(''),listBusy=ref(false),resultScope=ref('')
const availableTreatments=computed(()=>treatments.value.filter(t=>t.label.includes(treatmentSearch.value))),selectedNames=computed(()=>treatments.value.filter(t=>selectedTreatments.value.includes(t.id)).map(t=>t.label).join('、'))
const canLeave=useUnsaved(()=>drawer.value&&(!!patient.value||!!number.value||!!slot.value),()=>unknown.value)
function closeDrawer(){if(busy.value||!canLeave())return;drawer.value=false}
let listVersion=0,candidateVersion=0
watch([clinic,date,status,doctor],()=>{appointments.value=[];appointmentNext.value=null;slot.value=null;slots.value=[];candidateNext.value=null;candidateVersion++;patient.value=null;verification.value='';confirmed.value=false;step.value=1;loadAppointments()})
watch(selectedTreatments,()=>{candidateVersion++;slot.value=null;slots.value=[];candidateNext.value=null;step.value=1;confirmed.value=false})
let pending:PreparedCommand|undefined
const time=(at:string)=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(at))
const statusText:Record<string,string>={SCHEDULED:'待就诊',IN_PROGRESS:'诊疗中',COMPLETED:'已完成治疗',INVOICED:'已生成费用凭据',CANCELLED:'已取消'}
async function failed(failure:unknown){error.value=failure instanceof ApiFailure?`操作未完成：${failure.message}`:'服务暂不可用。';if(failure instanceof ApiFailure && [401,403].includes(failure.status)){patient.value=null;records.value=[];slots.value=[];appointments.value=[]}}
function range(){return {start:`${date.value}T00:00:00+08:00`,end:`${shiftDate(date.value,1)}T00:00:00+08:00`}}
async function loadAppointments(more=false){if(!date.value)return;const version=++listVersion;listBusy.value=true;error.value='';if(!more){appointments.value=[];appointmentNext.value=null;resultScope.value=''}try{const query=new URLSearchParams({...range(),role:'RECEPTION',limit:'50'});if(clinic.value)query.set('clinic_id',clinic.value);if(status.value)query.set('status',status.value);if(doctor.value)query.set('dentist_id',doctor.value);if(more&&appointmentNext.value)query.set('cursor',appointmentNext.value);const page=await api.get<{items:Appointment[];next_cursor:string|null}>('/api/v1/workspace/appointments?'+query);if(version!==listVersion)return;appointments.value=more?[...appointments.value,...page.items]:page.items;appointmentNext.value=page.next_cursor;resultScope.value=(clinics.value.find(c=>c.id===clinic.value)?.label??'全部授权诊所')+' · '+date.value}catch(failure){if(version===listVersion)await failed(failure)}finally{if(version===listVersion)listBusy.value=false}}
async function search(more=false){const version=++candidateVersion;busy.value=true;error.value='';slot.value=null;try{const query=new URLSearchParams({...range(),clinic_id:clinic.value,limit:'100'});for(const id of selectedTreatments.value)query.append('treatment_ids',id);if(more&&candidateNext.value)query.set('cursor',candidateNext.value);const page=await api.get<{items:Candidate[];next_cursor:string|null}>('/api/v1/appointment-candidates?'+query);if(version!==candidateVersion)return;slots.value=more?[...slots.value,...page.items]:page.items;candidateNext.value=page.next_cursor}catch(failure){if(version===candidateVersion)await failed(failure)}finally{busy.value=false}}
async function lookup(){busy.value=true;error.value='';patient.value=null;verification.value='';confirmed.value=false;records.value=[];try{const command=prepareCommand('lookupPatient','POST','/api/v1/patients/lookup',{patient_number:number.value,date_of_birth:birth.value,verification_basis:{clinic_id:clinic.value,person_confirmed:person.value,service_basis:basis.value}});const result=await api.execute<components['schemas']['PatientLookupResult']>(command);patient.value=result.data.patient;verification.value=result.data.verification_reference;let next:string|null=null;do{const page:{items:components['schemas']['AllergyView'][];next_cursor:string|null}=await api.get(`/api/v1/patients/${patient.value.patient_id}/allergy-records?limit=100${next?`&cursor=${encodeURIComponent(next)}`:''}`);records.value.push(...page.items);next=page.next_cursor}while(next)}catch(failure){await failed(failure)}finally{busy.value=false}}
async function execute(){if(!pending)return;busy.value=true;error.value='';try{const result=await api.execute<Appointment>(pending);notice.value=`预约已保存：${result.data.appointment_id}，状态为待就诊。`;pending=undefined;unknown.value=false;slot.value=null;confirmed.value=false;patient.value=null;number.value='';drawer.value=false;await loadAppointments()}catch(failure){if(failure instanceof UnknownOutcomeError){unknown.value=true;error.value='结果确认中，请保留当前页面并重新确认办理结果。'}else{pending=undefined;unknown.value=false;await failed(failure)}}finally{busy.value=false}}
async function book(){if(pending || !patient.value || !slot.value)return;const p=patient.value;const details={full_name:p.full_name,date_of_birth:p.date_of_birth,phone:p.phone,billing_address:p.billing_address,email:p.email??null,emergency_contact_name:p.emergency_contact_name,emergency_contact_phone:p.emergency_contact_phone};pending=prepareCommand('createAppointment','POST','/api/v1/appointments',{clinic_id:clinic.value,schedule_id:slot.value.schedule_id,scheduled_at:slot.value.starts_at,requested_treatment_ids:selectedTreatments.value,patient_id:p.patient_id,patient_verification_reference:verification.value,patient_details:details,allergy_confirmation_reference:p.allergy_confirmation_reference,allergy_declaration:{review_status:p.allergy_review_status,records:records.value.filter(a=>!a.is_retracted).map(a=>({allergy_id:a.allergy_id,severity_note:a.severity_note??null})),confirmed:confirmed.value}});await execute()}
async function catalog(path:string){const all:Catalog[]=[];let next:string|null=null;do{const page:{items:Catalog[];next_cursor:string|null}=await api.get(`${path}?limit=100${next?`&cursor=${encodeURIComponent(next)}`:''}`);all.push(...page.items);next=page.next_cursor}while(next);return all}
onMounted(async()=>{try{try{clinics.value=await catalog('/api/v1/clinics')}catch(failure){if(failure instanceof ApiFailure&&failure.status===403)clinics.value=(auth.identity?.clinic_scope??[]).map(id=>({id,label:'诊所 '+id,active:true}));else throw failure}if(can('searchAppointmentCandidates')||can('createAppointment'))treatments.value=await catalog('/api/v1/treatments');try{doctors.value=await catalog('/api/v1/dentists')}catch{};await loadAppointments()}catch(failure){await failed(failure)}})
</script>
<template><section>
<div class="page-heading"><div><p class="eyebrow">RECEPTION WORKSPACE</p><h1>预约工作台</h1><p class="muted">先定位就诊，再完成本人核验和相应办理。</p></div><button v-if="can('createAppointment')" class="compact-primary" @click="drawer=true;step=1">＋ 新建预约</button></div>
<p v-if="error" role="alert" class="error-message">{{error}}</p><p v-if="notice" role="status" class="success-message">{{notice}}</p>
<div class="surface"><div class="table-toolbar"><div class="filter-fields"><label>预约诊所<select v-model="clinic"><option value="">全部授权诊所</option><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.label}}</option></select></label><label>预约日期<input v-model="date" type="date"></label><label>接诊医生<select v-model="doctor"><option value="">全部医生</option><option v-for="d in doctors" :key="d.id" :value="d.id">{{d.label}}</option></select></label></div><button :disabled="listBusy" @click="loadAppointments()">{{listBusy?'正在读取…':'刷新预约'}}</button></div>
<div class="filter-tabs" aria-label="预约状态"><button :aria-pressed="status===''" @click="status=''">全部</button><button v-for="(label,key) in statusText" :key="key" :aria-pressed="status===key" @click="status=key">{{label}}</button></div>
<div class="table-toolbar"><p class="loaded-summary" role="status">{{listBusy?'正在读取所选范围…':resultScope}} · 已加载 {{appointments.length}} 条{{appointmentNext?'，还有更多记录':''}}</p><div class="filter-tabs"><button :aria-pressed="view==='list'" @click="view='list'">列表</button><button :aria-pressed="view==='calendar'" @click="view='calendar'">日程</button></div></div>
<div v-if="view==='list'" class="table-scroll"><table><thead><tr><th>预约时间</th><th>患者识别摘要</th><th>医生 / 诊所</th><th>期望治疗</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in appointments" :key="item.appointment_id"><td><strong>{{time(item.scheduled_at)}}</strong></td><td><strong>{{item.patient_name||'摘要未取得'}}</strong><small class="record-reference">{{item.patient_number}}</small></td><td>{{item.dentist_name}}<small class="record-reference">{{item.clinic_name}}</small></td><td>{{item.requested_treatments||'未指定'}}</td><td><span :class="['status-badge','state-'+item.status.toLowerCase()]">{{statusText[item.status]}}</span></td><td><AppointmentActions :appointment="item"/><details><summary>就诊信息</summary><small class="record-reference">预约 {{item.appointment_id}}</small><p v-if="item.cancellation_kind">取消分类：{{item.cancellation_kind==='NO_SHOW'?'已核实爽约':item.cancellation_kind==='PATIENT_CANCEL'?'患者取消':'诊所原因'}}</p></details></td></tr></tbody></table></div>
<ol v-else class="appointment-timeline"><li v-for="item in appointments" :key="item.appointment_id"><strong>{{time(item.scheduled_at)}} · {{item.patient_name}}</strong> · {{item.dentist_name}} · {{statusText[item.status]}} <AppointmentActions :appointment="item"/></li></ol>
<p v-if="!listBusy&&!error&&!appointments.length" class="empty-state">当前诊所、日期和状态下暂无匹配预约。可调整筛选或新建预约。</p><button v-if="appointmentNext" :disabled="listBusy" @click="loadAppointments(true)">加载更多预约</button><p class="workspace-note">列表摘要用于定位；到诊与资料维护仍须核实本人、出生日期及本次服务依据。</p></div>
<WorkspacePanel :open="drawer" title="新建预约" @close="closeDrawer"><div class="step-tabs"><button :aria-current="step===1?'step':undefined" @click="step=1">1 服务与时隙</button><button :disabled="!slot" :aria-current="step===2?'step':undefined" @click="step=2">2 本人核验与过敏</button><button :disabled="!patient||!slot" :aria-current="step===3?'step':undefined" @click="step=3">3 确认安排</button></div>
<p v-if="error" role="alert" class="error-message">{{error}}</p><div v-if="unknown" class="confirmation-summary"><p>结果确认中，请保留当前页面。</p><button :disabled="busy" @click="execute">重新确认办理结果</button></div>
<div v-show="step===1"><fieldset :disabled="busy||unknown"><label>实际服务诊所<select v-model="clinic" required><option value="" disabled>请选择一个实际诊所</option><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.label}}</option></select></label><label>预约日期<input v-model="date" type="date"></label><label class="wide">搜索期望治疗<input v-model="treatmentSearch" placeholder="按项目名称搜索"></label></fieldset><div class="treatment-options"><label v-for="t in availableTreatments" :key="t.id"><input v-model="selectedTreatments" :value="t.id" type="checkbox" :disabled="busy||unknown">{{t.label}}</label></div><p>已选：{{selectedNames||'尚未选择'}}</p><button class="compact-primary" :disabled="busy||unknown||!clinic||!selectedTreatments.length" @click="search()">查询合法可约时隙</button><div class="candidate-grid"><button v-for="item in slots" :key="item.schedule_id+item.starts_at" :aria-pressed="slot===item" :disabled="busy||unknown" @click="slot=item">{{time(item.starts_at)}}–{{time(item.ends_at)}} · {{item.dentist_name}}</button></div><button v-if="candidateNext" :disabled="busy||unknown" @click="search(true)">更多时隙</button><div class="dialog-actions"><button :disabled="!slot" @click="step=2">下一步 · 本人核验</button></div></div>
<div v-show="step===2"><form @submit.prevent="lookup"><fieldset :disabled="busy||unknown"><label>患者编号<input v-model="number" required @input="patient=null;verification='' "></label><label>出生日期<input v-model="birth" type="date" required @change="patient=null;verification='' "></label><label class="wide">本次服务依据<input v-model="basis" required maxlength="255" @input="patient=null;verification='' "></label><label><input v-model="person" type="checkbox" required @change="patient=null;verification='' ">已人工核实本人</label><button class="compact-primary">核验患者及过敏资料</button></fieldset></form><div v-if="patient" class="confirmation-summary"><h3>{{patient.full_name}} · {{patient.patient_number}}</h3><p>{{patient.allergy_review_status==='NO_KNOWN'?'已核实无已知过敏':patient.allergy_review_status==='RECORDED'?'存在已记录过敏':'尚未核实，请先维护患者过敏资料'}}</p><ul><li v-for="a in records.filter(r=>!r.is_retracted)" :key="a.allergy_id">{{a.allergy_name}} · {{a.severity_note||'未注明程度'}}</li></ul></div><div class="dialog-actions"><button :disabled="!patient||!slot" @click="step=3">下一步 · 确认安排</button></div></div>
<div v-if="step===3&&patient&&slot"><div class="confirmation-summary"><h3>{{patient.full_name}} · {{patient.patient_number}}</h3><p>实际诊所：{{clinics.find(c=>c.id===clinic)?.label}}</p><p>{{date}} {{time(slot.starts_at)}} · {{slot.dentist_name}}</p><p>期望项目：{{selectedNames}}</p><p>出生日期：{{patient.date_of_birth}} · 联系电话：{{patient.phone}}</p><p>账单地址：{{patient.billing_address}} · 邮箱：{{patient.email||'未填写'}}</p><p>紧急联系人：{{patient.emergency_contact_name}} · {{patient.emergency_contact_phone}}</p></div><label><input v-model="confirmed" type="checkbox" :disabled="busy||unknown">已核对全部资料、过敏记录及本次就诊安排</label><p v-if="!patient.allergy_confirmation_reference" role="status">请先完成过敏核验，再创建预约。</p><div class="dialog-actions"><button class="compact-primary" :disabled="busy||unknown||!confirmed||!patient.allergy_confirmation_reference" @click="book">确认创建预约</button></div></div>
</WorkspacePanel></section></template>
<style scoped>.candidate-grid{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}.candidate-grid [aria-pressed=true]{background:var(--brand);color:#fff}.treatment-options{display:grid;grid-template-columns:1fr 1fr;gap:12px;max-height:220px;overflow:auto;margin:16px 0}.appointment-timeline{border-left:3px solid var(--brand);padding-left:24px}.appointment-timeline li{padding:16px}.workspace-note{font-size:12px}@media(max-width:500px){.treatment-options{grid-template-columns:1fr}}</style>
